import { mkdir, readFile, rmdir, unlink, writeFile } from 'fs/promises'
import path from 'path'
import type { FileStorage } from './index'

/** `<taskId>/<uuid>`: both parts are generated by the server, never taken from a client. */
const KEY = /^[a-f\d]{24}\/[a-f\d-]{36}$/

/**
 * Development-only storage: files in a folder under the project (`.uploads`,
 * git-ignored). It is not durable or shared between servers, which is why
 * `getStorage()` never hands it out in production.
 */
export class LocalFileStorage implements FileStorage {
  readonly name = 'local-dev'
  private readonly root: string

  constructor(root: string = path.join(process.cwd(), '.uploads')) {
    this.root = path.resolve(root)
  }

  /** The file's path, only ever inside the storage folder. */
  private pathFor(key: string): string {
    if (!KEY.test(key)) throw new Error('Invalid storage key')
    const full = path.resolve(this.root, key)
    if (!full.startsWith(this.root + path.sep)) throw new Error('Invalid storage key')
    return full
  }

  async put(key: string, data: Buffer): Promise<void> {
    const file = this.pathFor(key)
    await mkdir(path.dirname(file), { recursive: true })
    await writeFile(file, data, { flag: 'wx' })
  }

  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.pathFor(key))
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null
      throw error
    }
  }

  async delete(key: string): Promise<void> {
    const file = this.pathFor(key)
    try {
      await unlink(file)
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error
    }
    // Tidy the task's folder once it is empty (rmdir refuses a non-empty one).
    await rmdir(path.dirname(file)).catch(() => {})
  }
}
